const fs = require('fs');
const src = JSON.parse(fs.readFileSync('/tmp/ne_countries.geojson', 'utf8'));

const GROUPS = {
  POR: { name: 'Portekiz', members: ['Portugal'], terrain: 'kıyı', prod: 2, capital: false },
  SPA: { name: 'İspanya', members: ['Spain'], terrain: 'dağ', prod: 3, capital: false },
  FRA: { name: 'Fransa', members: ['France'], terrain: 'ova', prod: 6, capital: true },
  UK:  { name: 'Birleşik Krallık', members: ['United Kingdom'], terrain: 'ada', prod: 7, capital: true },
  IRE: { name: 'İrlanda', members: ['Ireland'], terrain: 'ada', prod: 2, capital: false },
  BEN: { name: 'Benelüks', members: ['Belgium', 'Netherlands', 'Luxembourg'], terrain: 'ova', prod: 4, capital: false },
  GER: { name: 'Almanya', members: ['Germany', 'Austria'], terrain: 'ova', prod: 8, capital: true },
  BOH: { name: 'Bohemya', members: ['Czechia', 'Slovakia'], terrain: 'dağ', prod: 3, capital: false },
  SWI: { name: 'İsviçre', members: ['Switzerland'], terrain: 'dağ', prod: 2, capital: false },
  ITA: { name: 'İtalya', members: ['Italy'], terrain: 'dağ', prod: 5, capital: true },
  DEN: { name: 'Danimarka', members: ['Denmark'], terrain: 'ova', prod: 2, capital: false },
  NOR: { name: 'Norveç', members: ['Norway'], terrain: 'dağ', prod: 3, capital: false },
  SWE: { name: 'İsveç', members: ['Sweden'], terrain: 'orman', prod: 4, capital: false },
  FIN: { name: 'Finlandiya', members: ['Finland'], terrain: 'orman', prod: 3, capital: false },
  POL: { name: 'Polonya', members: ['Poland'], terrain: 'ova', prod: 4, capital: true },
  BAL: { name: 'Baltık Ülkeleri', members: ['Estonia', 'Latvia', 'Lithuania'], terrain: 'orman', prod: 3, capital: false },
  BLR: { name: 'Beyaz Rusya', members: ['Belarus'], terrain: 'orman', prod: 3, capital: false },
  UKR: { name: 'Ukrayna', members: ['Ukraine', 'Moldova'], terrain: 'ova', prod: 5, capital: false },
  RUS: { name: 'Sovyetler Birliği', members: ['Russia'], terrain: 'step', prod: 9, capital: true },
  CAU: { name: 'Kafkasya', members: ['Georgia', 'Armenia', 'Azerbaijan'], terrain: 'dağ', prod: 3, capital: false },
  HUN: { name: 'Macaristan', members: ['Hungary'], terrain: 'ova', prod: 3, capital: false },
  ROM: { name: 'Romanya', members: ['Romania'], terrain: 'ova', prod: 4, capital: true },
  BUL: { name: 'Bulgaristan', members: ['Bulgaria'], terrain: 'dağ', prod: 3, capital: false },
  ADR: { name: 'Hırvatistan', members: ['Slovenia', 'Croatia', 'Bosnia and Herzegovina', 'Montenegro'], terrain: 'dağ', prod: 2, capital: false },
  SRB: { name: 'Sırbistan', members: ['Serbia', 'Kosovo', 'North Macedonia'], terrain: 'dağ', prod: 3, capital: true },
  ALB: { name: 'Arnavutluk', members: ['Albania'], terrain: 'dağ', prod: 1, capital: false },
  GRE: { name: 'Yunanistan', members: ['Greece'], terrain: 'dağ', prod: 3, capital: true },
  TUR: { name: 'Türkiye', members: ['Turkey'], terrain: 'dağ', prod: 4, capital: true },
  LBY: { name: 'Libya', members: ['Libya'], terrain: 'çöl', prod: 1, capital: false },
  EGY: { name: 'Mısır', members: ['Egypt'], terrain: 'çöl', prod: 2, capital: false },
  FNA: { name: 'Fransız Kuzey Afrikası', members: ['Morocco', 'Algeria', 'Tunisia'], terrain: 'çöl', prod: 2, capital: false },
  SYR: { name: 'Levant', members: ['Syria', 'Lebanon', 'Israel', 'Palestine', 'Jordan'], terrain: 'çöl', prod: 2, capital: false },
  IRQ: { name: 'Irak', members: ['Iraq'], terrain: 'çöl', prod: 2, capital: false },
  ISL: { name: 'İzlanda', members: ['Iceland'], terrain: 'ada', prod: 1, capital: false },
};

const BBOX = { minLon: -13, maxLon: 60, minLat: 27, maxLat: 72 };
const LON0 = -13, LON1 = 60, LAT0 = 27, LAT1 = 72;
const MERC = lat => Math.log(Math.tan(Math.PI / 4 + (lat * Math.PI) / 360));
const MX0 = (LON0 * Math.PI) / 180, MX1 = (LON1 * Math.PI) / 180;
const MY0 = MERC(LAT0), MY1 = MERC(LAT1);
const W = 1600, H = 1000;
const PAD = 18;
function project(lon, lat) {
  const x = ((lon * Math.PI) / 180 - MX0) / (MX1 - MX0);
  const y = (MY1 - MERC(lat)) / (MY1 - MY0);
  return [PAD + x * (W - PAD * 2), PAD + y * (H - PAD * 2)];
}

function clipRing(ring, bbox) {
  // Sutherland-Hodgman against lon/lat rectangle
  const edges = [
    { inside: p => p[0] >= bbox.minLon, intersect: (a, b) => { const t = (bbox.minLon - a[0]) / (b[0] - a[0]); return [bbox.minLon, a[1] + t * (b[1] - a[1])]; } },
    { inside: p => p[0] <= bbox.maxLon, intersect: (a, b) => { const t = (bbox.maxLon - a[0]) / (b[0] - a[0]); return [bbox.maxLon, a[1] + t * (b[1] - a[1])]; } },
    { inside: p => p[1] >= bbox.minLat, intersect: (a, b) => { const t = (bbox.minLat - a[1]) / (b[1] - a[1]); return [a[0] + t * (b[0] - a[0]), bbox.minLat]; } },
    { inside: p => p[1] <= bbox.maxLat, intersect: (a, b) => { const t = (bbox.maxLat - a[1]) / (b[1] - a[1]); return [a[0] + t * (b[0] - a[0]), bbox.maxLat]; } },
  ];
  let out = ring;
  for (const e of edges) {
    const inp = out; out = [];
    if (!inp.length) break;
    for (let i = 0; i < inp.length; i++) {
      const cur = inp[i], prev = inp[(i + inp.length - 1) % inp.length];
      const ci = e.inside(cur), pi = e.inside(prev);
      if (ci) { if (!pi) out.push(e.intersect(prev, cur)); out.push(cur); }
      else if (pi) out.push(e.intersect(prev, cur));
    }
  }
  return out;
}

function ringArea(ring) {
  let a = 0;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) a += (ring[j][0] * ring[i][1] - ring[i][0] * ring[j][1]);
  return Math.abs(a / 2);
}

function simplify(points, tol) {
  if (points.length <= 4) return points;
  const sq = tol * tol;
  function sqSeg(p, a, b) {
    let x = a[0], y = a[1], dx = b[0] - x, dy = b[1] - y;
    if (dx !== 0 || dy !== 0) {
      const t = ((p[0] - x) * dx + (p[1] - y) * dy) / (dx * dx + dy * dy);
      if (t > 1) { x = b[0]; y = b[1]; } else if (t > 0) { x += dx * t; y += dy * t; }
    }
    dx = p[0] - x; dy = p[1] - y; return dx * dx + dy * dy;
  }
  function step(first, last, out) {
    let maxD = sq, idx = -1;
    for (let i = first + 1; i < last; i++) { const d = sqSeg(points[i], points[first], points[last]); if (d > maxD) { maxD = d; idx = i; } }
    if (idx > 0) { step(first, idx, out); out.push(points[idx]); step(idx, last, out); }
  }
  const out = [points[0]];
  step(0, points.length - 1, out);
  out.push(points[points.length - 1]);
  return out;
}

const features = new Map(src.features.map(f => [f.properties.ADMIN, f]));
const regions = [];
for (const [id, cfg] of Object.entries(GROUPS)) {
  const rings = [];
  for (const member of cfg.members) {
    const f = features.get(member);
    if (!f) { console.warn('missing', member); continue; }
    const geom = f.geometry;
    const polys = geom.type === 'Polygon' ? [geom.coordinates] : geom.coordinates;
    for (const poly of polys) {
      for (let ri = 0; ri < poly.length; ri++) {
        let ring = poly[ri].map(([lon, lat]) => [lon, lat]);
        ring = clipRing(ring, BBOX);
        if (ring.length < 3) continue;
        const area = ringArea(ring);
        if (ri === 0 && area < 0.025) continue;
        if (ri > 0 && area < 0.08) continue;
        const simplified = simplify(ring, 0.055);
        if (simplified.length < 3) continue;
        const projected = simplified.map(([lon, lat]) => project(lon, lat).map(v => +v.toFixed(1)));
        rings.push({ points: projected, area: ringArea(simplified), source: member, hole: ri > 0 });
      }
    }
  }
  // keep only outer rings, largest first; holes dropped for simplicity
  const outers = rings.filter(r => !r.hole).sort((a, b) => b.area - a.area);
  const polys = outers.map(r => r.points);
  if (!polys.length) { console.warn('no geometry', id); continue; }
  // label point: weighted centroid of largest ring, fallback to bbox center; ensure inside-ish
  const main = polys[0];
  let A = 0, cx = 0, cy = 0;
  for (let i = 0, j = main.length - 1; i < main.length; j = i++) {
    const f = main[j][0] * main[i][1] - main[i][0] * main[j][1];
    A += f; cx += (main[j][0] + main[i][0]) * f; cy += (main[j][1] + main[i][1]) * f;
  }
  cx /= 3 * A; cy /= 3 * A;
  // scan for interior point far from edges
  const xs = main.map(p => p[0]), ys = main.map(p => p[1]);
  const bx0 = Math.min(...xs), bx1 = Math.max(...xs), by0 = Math.min(...ys), by1 = Math.max(...ys);
  function inside(pt, ring) {
    let c = false;
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
      const [xi, yi] = ring[i], [xj, yj] = ring[j];
      if ((yi > pt[1]) !== (yj > pt[1]) && pt[0] < ((xj - xi) * (pt[1] - yi)) / (yj - yi) + xi) c = !c;
    }
    return c;
  }
  let best = [cx, cy], bestD = -1;
  for (let ix = 0; ix <= 24; ix++) for (let iy = 0; iy <= 24; iy++) {
    const p = [bx0 + (bx1 - bx0) * ix / 24, by0 + (by1 - by0) * iy / 24];
    if (!inside(p, main)) continue;
    let d = Infinity;
    for (let i = 0, j = main.length - 1; i < main.length; j = i++) {
      const [ax, ay] = main[j], [bx, by] = main[i];
      const dx = bx - ax, dy = by - ay;
      const t = Math.max(0, Math.min(1, ((p[0] - ax) * dx + (p[1] - ay) * dy) / (dx * dx + dy * dy || 1)));
      const ex = ax + t * dx - p[0], ey = ay + t * dy - p[1];
      d = Math.min(d, ex * ex + ey * ey);
    }
    if (d > bestD) { bestD = d; best = p; }
  }
  if (!inside(best, main)) best = [cx, cy];
  regions.push({ id, name: cfg.name, terrain: cfg.terrain, prod: cfg.prod, capital: cfg.capital, polys, label: best.map(v => +v.toFixed(1)), area: +outers.reduce((s, r) => s + r.area, 0).toFixed(2) });
}

// adjacency: boundary proximity in projected space
const DIST = 5.2;
function near(a, b) {
  const A = a.polys.flat(), B = b.polys.flat();
  let best = Infinity;
  // coarse bbox check
  const ab = [Math.min(...A.map(p=>p[0])), Math.min(...A.map(p=>p[1])), Math.max(...A.map(p=>p[0])), Math.max(...A.map(p=>p[1]))];
  const bb = [Math.min(...B.map(p=>p[0])), Math.min(...B.map(p=>p[1])), Math.max(...B.map(p=>p[0])), Math.max(...B.map(p=>p[1]))];
  if (ab[0] - DIST > bb[2] || bb[0] - DIST > ab[2] || ab[1] - DIST > bb[3] || bb[1] - DIST > ab[3]) return false;
  // sample every point against every point of other (reduced)
  const sa = A.filter((_, i) => i % 2 === 0), sb = B.filter((_, i) => i % 2 === 0);
  for (const p of sa) for (const q of sb) {
    const dx = p[0] - q[0], dy = p[1] - q[1], d = dx * dx + dy * dy;
    if (d < best) best = d;
    if (best < DIST * DIST) return true;
  }
  return best < DIST * DIST;
}
const manual = [
  ['UK','FRA'],['UK','BEN'],['UK','NOR'],['UK','ISL'],['IRE','UK'],['DEN','SWE'],['DEN','NOR'],
  ['SWE','BAL'],['SWE','FIN'],['ITA','LBY'],['ITA','ALB'],['ITA','GRE'],['TUR','UKR'],['RUS','TUR'],
  ['FNA','SPA'],['FNA','ITA'],['FNA','LBY'],['LBY','EGY'],['LBY','GRE'],['ISL','NOR'],
  ['EGY','SYR'],['SYR','TUR'],['SYR','IRQ'],['IRQ','TUR'],['CAU','TUR'],
  ['GER','SWE'],['GER','NOR'],['GER','UK'],['BAL','FIN'],['RUS','CAU'],['RUS','FIN'],['RUS','NOR'],
  ['SPA','POR'],['FRA','SPA'],['FRA','BEN'],['FRA','GER'],['FRA','SWI'],['FRA','ITA'],['FRA','UK'],
  ['BEN','GER'],['GER','BOH'],['GER','POL'],['GER','DEN'],['GER','SWI'],['GER','ITA'],['GER','HUN'],['GER','ADR'],
  ['BOH','POL'],['BOH','HUN'],['SWI','ITA'],['POL','BAL'],['POL','BLR'],['POL','ROM'],['POL','GER'],
  ['BAL','BLR'],['BAL','RUS'],['BLR','RUS'],['BLR','UKR'],['UKR','RUS'],['UKR','ROM'],['UKR','HUN'],
  ['HUN','ROM'],['HUN','ADR'],['HUN','SRB'],['ROM','SRB'],['ROM','BUL'],['BUL','SRB'],['BUL','GRE'],['BUL','TUR'],
  ['ADR','SRB'],['ADR','ITA'],['ADR','ALB'],['SRB','ALB'],['SRB','GRE'],['ALB','GRE'],['GRE','TUR'],
  ['TUR','CAU'],['CAU','RUS'],['EGY','LBY'],['FNA','LBY'],['FNA','SPA'],['IRQ','SYR'],['IRQ','TUR'],
];
const neigh = {};
for (const r of regions) neigh[r.id] = new Set();
for (let i = 0; i < regions.length; i++) for (let j = i + 1; j < regions.length; j++) {
  if (near(regions[i], regions[j])) { neigh[regions[i].id].add(regions[j].id); neigh[regions[j].id].add(regions[i].id); }
}
for (const [a, b] of manual) { if (neigh[a] && neigh[b]) { neigh[a].add(b); neigh[b].add(a); } }
for (const r of regions) r.neighbors = [...neigh[r.id]].sort();

const out = { width: W, height: H, bbox: BBOX, regions };
