.res-glyph.coin:after{content:"";position:absolute;inset:5px;border:1px solid rgba(64,45,15,.6);border-radius:50%}
.res-glyph.income{border:1px solid rgba(111,177,138,.8);transform:rotate(45deg);border-radius:2px;background:linear-gradient(135deg,rgba(111,177,138,.38),rgba(111,177,138,.06));width:14px;height:14px;margin:0 2px}
