.morale-track span{display:block;height:100%;width:65%;background:linear-gradient(90deg,#b5503f,#d3af69,#6fb18a);transition:width .5s ease}

/* ============================================================
   YAN PANELLER
   ============================================================ */
.side-panel{
  position:absolute;top:92px;bottom:106px;z-index:16;display:flex;flex-direction:column;
  width:300px;border:1px solid var(--line);border-radius:4px;
  background:linear-gradient(180deg,rgba(10,19,25,.94),rgba(6,12,17,.92));
  box-shadow:0 20px 60px rgba(0,0,0,.45),inset 0 1px 0 rgba(255,255,255,.035);
  backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);
  transition:transform .28s cubic-bezier(.22,.8,.3,1),opacity .28s ease;
}
