.panel-head{display:flex;align-items:flex-start;justify-content:space-between;gap:10px;padding:17px 16px 13px;border-bottom:1px solid var(--line-soft)}
.panel-head h2{margin:0;font-family:var(--serif);font-size:14px;letter-spacing:.17em;color:var(--text)}
