.front-summary .summary-sub{font-size:9px;letter-spacing:.14em;color:var(--faint);text-transform:uppercase;margin-bottom:18px}
.balance{display:flex;height:7px;overflow:hidden;background:rgba(236,229,214,.08);margin:7px 0 5px}
.balance span{height:100%;transition:width .5s ease}
.balance .b-axis{background:linear-gradient(90deg,#8d3b2f,var(--axis))}
.balance .b-allies{background:linear-gradient(90deg,var(--allies),#75a7cd)}
.balance .b-neutral{background:var(--neutral)}
.legend-row{display:flex;justify-content:space-between;font-size:8px;letter-spacing:.12em;color:var(--faint);text-transform:uppercase}
.tip-card{margin-top:20px;padding:13px;border:1px solid var(--line-soft);background:rgba(211,175,105,.03)}
.tip-card h4{margin:0 0 6px;font-size:9px;letter-spacing:.18em;color:var(--gold);text-transform:uppercase}
.tip-card p{margin:0;font-size:10px;line-height:1.6;color:var(--muted)}

/* ============================================================
   ALT BAR
   ============================================================ */
.bottom-bar{
  position:absolute;left:0;right:0;bottom:0;height:88px;z-index:18;
  display:flex;align-items:center;justify-content:space-between;gap:16px;
  padding:0 18px calc(env(safe-area-inset-bottom,0px) + 4px);
  background:linear-gradient(0deg,rgba(4,10,14,.97) 0%,rgba(4,10,14,.8) 58%,rgba(4,10,14,0) 100%);
  pointer-events:none;
}
.bottom-bar>*{pointer-events:auto}
.bottom-hint{display:flex;align-items:center;gap:9px;font-size:10px;letter-spacing:.06em;color:var(--muted);max-width:540px;line-height:1.45}
.hint-icon{color:var(--gold);font-size:8px}
.bottom-actions{display:flex;align-items:center;gap:12px;flex:none}
.zoom-group{display:flex;gap:4px;margin-right:4px}
.end-turn{
  min-width:190px;height:52px;flex-direction:column;gap:2px;line-height:1;
  font-size:11px;letter-spacing:.2em;
}
.end-turn small{font-size:8px;letter-spacing:.18em;opacity:.68;font-weight:700}
.end-turn:disabled{filter:grayscale(.5)}

/* ============================================================
   BİLDİRİMLER
   ============================================================ */
.ai-banner{
  position:absolute;top:92px;left:50%;transform:translateX(-50%);z-index:22;
  display:flex;align-items:center;gap:10px;padding:10px 18px;
  background:rgba(45,20,17,.92);border:1px solid rgba(208,100,82,.45);
  font-size:9px;letter-spacing:.22em;color:#f0c3b9;text-transform:uppercase;
  box-shadow:0 10px 40px rgba(0,0,0,.5);
}
.spinner{width:10px;height:10px;border:1.5px solid rgba(240,195,185,.25);border-top-color:#f0c3b9;border-radius:50%;animation:spin .8s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.battle-banner{
  position:absolute;top:96px;left:50%;transform:translateX(-50%);z-index:23;
  min-width:300px;max-width:min(520px,90vw);padding:12px 20px;text-align:center;
  background:linear-gradient(180deg,rgba(18,31,39,.97),rgba(9,17,22,.97));
  border:1px solid var(--line);box-shadow:0 16px 50px rgba(0,0,0,.55);
  animation:bannerIn .3s cubic-bezier(.2,.8,.3,1) both;
}
.battle-banner.win{border-color:rgba(111,177,138,.55)}
.battle-banner.loss{border-color:rgba(208,100,82,.55)}
.battle-banner .bb-kicker{font-size:8px;letter-spacing:.26em;color:var(--gold);text-transform:uppercase;margin-bottom:5px}
.battle-banner .bb-title{font-family:var(--serif);font-size:18px;letter-spacing:.06em;margin-bottom:4px}
.battle-banner .bb-detail{font-size:10px;color:var(--muted);letter-spacing:.04em}
@keyframes bannerIn{from{opacity:0;transform:translate(-50%,-10px)}to{opacity:1;transform:translate(-50%,0)}}
.toast-stack{position:absolute;right:18px;bottom:106px;z-index:30;display:flex;flex-direction:column;gap:7px;align-items:flex-end;pointer-events:none}
.toast{
  max-width:300px;padding:9px 13px;background:rgba(9,17,22,.96);border:1px solid var(--line);
  border-left:2px solid var(--gold);font-size:10px;line-height:1.45;color:var(--text);
  box-shadow:0 10px 30px rgba(0,0,0,.45);animation:toastIn .25s ease both;
}
.toast.bad{border-left-color:var(--red)}
.toast.good{border-left-color:var(--green)}
.toast.out{animation:toastOut .25s ease both}
@keyframes toastIn{from{opacity:0;transform:translateX(12px)}to{opacity:1;transform:none}}
@keyframes toastOut{to{opacity:0;transform:translateX(12px)}}
.map-tooltip{
  position:fixed;z-index:31;pointer-events:none;min-width:130px;padding:8px 10px;
  background:rgba(7,14,19,.96);border:1px solid var(--line);box-shadow:0 10px 30px rgba(0,0,0,.5);
  font-size:10px;line-height:1.4;transform:translate(14px,14px);
}
.map-tooltip .tt-name{font-family:var(--serif);font-size:13px;letter-spacing:.04em;margin-bottom:3px}
.map-tooltip .tt-owner{font-size:8px;letter-spacing:.16em;text-transform:uppercase;margin-bottom:3px}
.map-tooltip .tt-line{color:var(--muted)}

/* ============================================================
   GİRİŞ EKRANI
   ============================================================ */
.intro{z-index:40;overflow:hidden;background:transparent}
.intro-shade{
  position:absolute;inset:0;pointer-events:none;
  background:
    radial-gradient(ellipse at 26% 44%,rgba(4,10,14,.1) 0%,rgba(4,10,14,.55) 58%,rgba(3,8,11,.9) 100%),
    linear-gradient(90deg,rgba(3,8,11,.86) 0%,rgba(3,8,11,.44) 46%,rgba(3,8,11,.78) 100%),
    linear-gradient(0deg,rgba(3,8,11,.94),transparent 35%);
}
.intro-grid{
  position:relative;z-index:2;height:calc(100% - 54px);max-width:1480px;margin:0 auto;
  padding:5vh 5vw 0;display:grid;grid-template-columns:1.06fr .94fr;gap:4vw;align-items:center;
}
.intro-left{max-width:640px;animation:introUp .8s ease both}
.kicker{
  display:flex;align-items:center;gap:12px;font-size:9px;letter-spacing:.34em;color:var(--gold);
  text-transform:uppercase;font-weight:700;margin-bottom:22px;
}
.kicker span{display:block;width:30px;height:1px;background:linear-gradient(90deg,transparent,var(--gold-dim))}
.kicker span:last-child{background:linear-gradient(90deg,var(--gold-dim),transparent)}
.intro h1{
  margin:0;font-family:var(--serif);font-size:clamp(64px,9.4vw,142px);line-height:.78;
  letter-spacing:-.035em;color:#f2ebdc;text-shadow:0 8px 40px rgba(0,0,0,.55);
}
.intro h1 em{font-style:normal;color:var(--gold-2);position:relative;display:inline-block}
.intro h1 em:after{
  content:"";position:absolute;left:2%;right:2%;bottom:-2px;height:2px;
  background:linear-gradient(90deg,transparent,var(--gold),transparent);opacity:.65;
}
.tagline{font-family:var(--serif);font-style:italic;font-size:clamp(16px,1.7vw,22px);color:#d8d0be;margin:24px 0 14px;letter-spacing:.02em}
.intro-desc{max-width:500px;font-size:12px;line-height:1.85;color:#a6a99e;letter-spacing:.02em;margin:0}
.intro-actions{display:flex;gap:10px;margin-top:26px;flex-wrap:wrap}
.intro-stats{display:flex;gap:clamp(18px,3vw,42px);margin-top:34px;padding-top:18px;border-top:1px solid rgba(211,175,105,.14)}
.intro-stats div{display:flex;flex-direction:column;gap:5px}
.intro-stats b{font-family:var(--serif);font-size:24px;color:var(--gold-2);font-weight:400;line-height:1}
.intro-stats span{font-size:7px;letter-spacing:.2em;color:var(--faint);text-transform:uppercase}
.intro-right{animation:introUp .8s .12s ease both;min-height:0}
.selection-panel{
  max-height:80vh;overflow-y:auto;padding:24px 24px 20px;border:1px solid var(--line);
  background:linear-gradient(180deg,rgba(11,21,27,.92),rgba(6,13,18,.94));
  box-shadow:0 30px 90px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.035);
  backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px);
  scrollbar-width:thin;scrollbar-color:var(--gold-dim) transparent;
}
.selection-head{margin-bottom:12px}
.selection-head h2{margin:0;font-family:var(--serif);font-size:17px;letter-spacing:.16em;color:var(--text)}
.side-head{margin-top:22px}
.scenario-list{display:flex;flex-direction:column;gap:8px}
.scenario{
  position:relative;display:flex;align-items:stretch;gap:14px;padding:13px 13px 12px;text-align:left;
  border:1px solid rgba(236,229,214,.11);background:rgba(236,229,214,.022);cursor:pointer;
  transition:all .18s ease;overflow:hidden;
}
.scenario:hover{border-color:rgba(211,175,105,.32);background:rgba(211,175,105,.045)}
.scenario.active{border-color:rgba(211,175,105,.62);background:linear-gradient(90deg,rgba(211,175,105,.1),rgba(211,175,105,.02))}
.scenario.active:before{content:"";position:absolute;left:0;top:0;bottom:0;width:2px;background:var(--gold)}
.scenario .sc-year{
  width:60px;flex:none;font-family:var(--serif);font-size:25px;color:var(--gold-2);line-height:1;
  padding-top:2px;letter-spacing:-.02em;
}
.scenario .sc-body{min-width:0;flex:1}
.scenario .sc-kicker{font-size:7px;letter-spacing:.2em;color:var(--faint);text-transform:uppercase;margin-bottom:3px}
.scenario .sc-title{font-size:12px;letter-spacing:.08em;font-weight:700;color:var(--text);text-transform:uppercase;margin-bottom:3px}
.scenario .sc-desc{font-size:9px;line-height:1.45;color:var(--muted)}
.scenario .sc-tag{align-self:center;font-size:7px;letter-spacing:.16em;color:var(--gold);border:1px solid rgba(211,175,105,.3);padding:3px 5px;text-transform:uppercase;white-space:nowrap}
.side-list{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.side-card{
  position:relative;display:flex;flex-direction:column;align-items:flex-start;gap:7px;text-align:left;
  padding:12px 11px;border:1px solid rgba(236,229,214,.11);background:rgba(236,229,214,.022);cursor:pointer;
  transition:all .18s ease;overflow:hidden;
}
.side-card:hover{border-color:rgba(211,175,105,.32);background:rgba(211,175,105,.045)}
.side-card.active{border-color:rgba(211,175,105,.62);background:linear-gradient(135deg,rgba(211,175,105,.1),rgba(211,175,105,.02))}
.side-card .sc-emblem{width:32px;height:32px}
.side-card .sc-emblem svg{width:100%;height:100%}
.side-card .side-name{font-size:9px;letter-spacing:.13em;font-weight:700;text-transform:uppercase;line-height:1.35}
.side-card .side-motto{font-size:8px;line-height:1.4;color:var(--faint)}
.side-card .side-diff{font-size:7px;letter-spacing:.16em;text-transform:uppercase;color:var(--gold);margin-top:1px}
.difficulty-row{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:20px 0 12px}
.difficulty-row>span{font-size:8px;letter-spacing:.2em;color:var(--faint)}
.segmented{display:flex;border:1px solid rgba(236,229,214,.13);padding:2px;gap:2px}
.segmented button{
  border:0;background:none;color:var(--faint);font-size:8px;letter-spacing:.12em;font-weight:700;
  padding:7px 10px;cursor:pointer;transition:all .15s;
}
.segmented button:hover{color:var(--text)}
.segmented button.active{background:rgba(211,175,105,.15);color:var(--gold-2);box-shadow:inset 0 0 0 1px rgba(211,175,105,.25)}
.save-note{font-size:8px;letter-spacing:.12em;color:var(--faint);text-align:center;margin:10px 0 0}
.intro-footer{
  position:absolute;left:0;right:0;bottom:0;height:54px;z-index:2;display:flex;align-items:center;justify-content:space-between;
  padding:0 5vw;border-top:1px solid rgba(211,175,105,.1);
  font-size:8px;letter-spacing:.22em;color:var(--faint);text-transform:uppercase;
}
.footer-quote{font-family:var(--serif);font-style:italic;letter-spacing:.03em;text-transform:none;font-size:10px;color:#8d9188}
@keyframes introUp{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}

/* ============================================================
   SON EKRAN
   ============================================================ */
.end-screen{
  z-index:50;display:grid;place-items:center;padding:20px;overflow-y:auto;
  background:
    radial-gradient(ellipse at 50% 42%,rgba(211,175,105,.1),transparent 55%),
    linear-gradient(180deg,rgba(3,8,11,.88),rgba(3,8,11,.97));
  backdrop-filter:blur(3px);
}
.end-card{
  width:min(700px,94vw);padding:34px 40px 30px;text-align:center;border:1px solid var(--line);
  background:linear-gradient(180deg,rgba(12,22,29,.97),rgba(6,13,18,.98));
  box-shadow:0 40px 120px rgba(0,0,0,.65),inset 0 1px 0 rgba(255,255,255,.04);
  animation:introUp .6s ease both;
}
.end-emblem{width:64px;height:64px;margin:0 auto 12px}
.end-emblem svg{width:100%;height:100%}
.end-card h1{margin:8px 0 4px;font-family:var(--serif);font-size:clamp(40px,7vw,68px);letter-spacing:.1em;color:var(--gold-2);line-height:1}
.end-card #end-subtitle{margin:0 0 24px;font-family:var(--serif);font-style:italic;color:var(--muted);font-size:14px}
.end-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:rgba(236,229,214,.1);border:1px solid rgba(236,229,214,.1);margin:0 0 22px}
.end-stat{background:rgba(9,17,22,.96);padding:14px 8px}
.end-stat b{display:block;font-family:var(--serif);font-size:24px;color:var(--text);font-weight:400;line-height:1}
.end-stat span{display:block;font-size:7px;letter-spacing:.18em;color:var(--faint);text-transform:uppercase;margin-top:6px}
.end-card blockquote{margin:0 0 24px;padding:14px 18px;border-left:2px solid var(--gold-dim);border-right:2px solid var(--gold-dim);font-family:var(--serif);font-style:italic;font-size:12px;line-height:1.7;color:#b8b4a7}
.end-actions{display:flex;gap:10px;justify-content:center;flex-wrap:wrap}
.end-actions .btn{min-width:170px}

/* ============================================================
   MODAL
   ============================================================ */
.modal-layer{
  position:fixed;inset:0;z-index:60;display:grid;place-items:center;padding:18px;
  background:rgba(2,7,10,.76);backdrop-filter:blur(7px);-webkit-backdrop-filter:blur(7px);
  animation:modalFade .2s ease both;
}
@keyframes modalFade{from{opacity:0}to{opacity:1}}
.modal-card{
  position:relative;width:min(560px,94vw);max-height:88dvh;overflow-y:auto;
  border:1px solid rgba(211,175,105,.36);
  background:linear-gradient(180deg,rgba(14,25,32,.98),rgba(7,14,19,.99));
  box-shadow:0 40px 120px rgba(0,0,0,.7),inset 0 1px 0 rgba(255,255,255,.04);
  padding:28px 30px 26px;animation:modalIn .28s cubic-bezier(.2,.8,.3,1) both;
  scrollbar-width:thin;scrollbar-color:var(--gold-dim) transparent;
}
.modal-card:before{content:"";position:absolute;inset:6px;border:1px solid rgba(211,175,105,.08);pointer-events:none}
@keyframes modalIn{from{opacity:0;transform:translateY(14px) scale(.985)}to{opacity:1;transform:none}}
.modal-close{position:absolute;top:12px;right:12px;z-index:2}
.modal-kicker{display:flex;align-items:center;gap:10px;font-size:8px;letter-spacing:.24em;color:var(--gold);text-transform:uppercase;margin-bottom:14px}
.modal-kicker .rule{flex:1;height:1px;background:linear-gradient(90deg,var(--gold-dim),transparent)}
.modal-date{font-size:8px;letter-spacing:.18em;color:var(--faint);text-transform:uppercase}
.modal-title{margin:8px 0 6px;font-family:var(--serif);font-size:clamp(26px,4.5vw,38px);letter-spacing:.04em;line-height:1.05;color:var(--text)}
.modal-sub{font-family:var(--serif);font-style:italic;font-size:12px;color:var(--gold-2);margin:0 0 16px}
.modal-rule{height:1px;background:linear-gradient(90deg,var(--gold-dim),rgba(211,175,105,.05));margin:0 0 16px}
.modal-text{font-size:12px;line-height:1.8;color:#b9b8ad;margin:0 0 18px}
.effect-list{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 20px}
.effect-chip{font-size:8px;letter-spacing:.1em;text-transform:uppercase;color:var(--gold-2);border:1px solid rgba(211,175,105,.3);background:rgba(211,175,105,.06);padding:5px 8px}
.modal-actions{display:flex;gap:9px;justify-content:flex-end;flex-wrap:wrap;margin-top:6px}
.modal-actions .btn{min-width:120px}
.choice-list{display:flex;flex-direction:column;gap:8px;margin:0 0 18px}
.choice{
  display:flex;flex-direction:column;align-items:flex-start;gap:4px;text-align:left;width:100%;
  padding:12px 14px;border:1px solid rgba(236,229,214,.14);background:rgba(236,229,214,.025);
  cursor:pointer;transition:all .16s;
}
.choice:hover{border-color:rgba(211,175,105,.5);background:rgba(211,175,105,.07)}
.choice b{font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--gold-2)}
.choice span{font-size:9px;line-height:1.45;color:var(--muted)}

/* saldırı / taşıma */
.force-grid{display:grid;grid-template-columns:1fr auto 1fr;gap:10px;align-items:center;margin:0 0 18px}
.force-box{padding:12px;border:1px solid rgba(236,229,214,.12);background:rgba(236,229,214,.025);text-align:center}
.force-box .fb-name{font-size:9px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin-bottom:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.force-box .fb-troops{font-family:var(--serif);font-size:30px;line-height:1;color:var(--text)}
.force-box .fb-side{font-size:7px;letter-spacing:.16em;text-transform:uppercase;margin-top:6px}
.force-box.attacker{border-color:rgba(208,100,82,.32)}
.force-box.defender{border-color:rgba(75,127,168,.32)}
.force-vs{font-family:var(--serif);font-size:11px;letter-spacing:.1em;color:var(--faint)}
.odds-row{display:flex;align-items:center;gap:10px;margin:0 0 8px}
.odds-track{flex:1;height:6px;background:rgba(208,100,82,.18);overflow:hidden;display:flex}
.odds-track span{height:100%;background:linear-gradient(90deg,#8e3d30,#d06452,#d3af69,#6fb18a);transition:width .35s ease}
.odds-value{font-size:10px;letter-spacing:.1em;color:var(--text);font-variant-numeric:tabular-nums;min-width:42px;text-align:right}
.odds-label{font-size:8px;letter-spacing:.16em;color:var(--faint);text-transform:uppercase;margin-bottom:16px}
.modifier-list{display:flex;flex-direction:column;gap:5px;margin:0 0 18px}
.modifier{display:flex;justify-content:space-between;font-size:9px;letter-spacing:.04em;color:var(--muted);padding:5px 0;border-bottom:1px solid rgba(236,229,214,.06)}
.modifier b{font-weight:500;color:var(--text)}
.modifier.good b{color:var(--green)}.modifier.bad b{color:var(--red)}
.range-row{display:flex;align-items:center;gap:12px;margin:8px 0 18px}
.range-row input[type=range]{flex:1;accent-color:var(--gold);height:4px}
.range-value{font-family:var(--serif);font-size:24px;color:var(--gold-2);min-width:48px;text-align:right;line-height:1}
.quick-row{display:flex;gap:6px;margin-bottom:18px}
.quick-row button{flex:1;font-size:8px;letter-spacing:.12em;padding:7px;border:1px solid rgba(236,229,214,.14);background:rgba(236,229,214,.03);color:var(--muted);cursor:pointer}
.quick-row button:hover{border-color:var(--gold-dim);color:var(--gold-2)}

/* menü / yardım */
.menu-list{display:flex;flex-direction:column;gap:7px;margin:16px 0 0}
.menu-item{
  display:flex;align-items:center;justify-content:space-between;gap:12px;padding:13px 14px;
  border:1px solid rgba(236,229,214,.11);background:rgba(236,229,214,.025);cursor:pointer;
  text-align:left;transition:all .16s;width:100%;
}
.menu-item:hover{border-color:rgba(211,175,105,.38);background:rgba(211,175,105,.05)}
.menu-item b{font-size:10px;letter-spacing:.14em;text-transform:uppercase;font-weight:700}
.menu-item span{font-size:8px;letter-spacing:.08em;color:var(--faint)}
.help-steps{display:flex;flex-direction:column;gap:12px;margin:16px 0 20px}
.help-step{display:flex;gap:12px;align-items:flex-start}
.help-num{
  width:24px;height:24px;flex:none;display:grid;place-items:center;border:1px solid rgba(211,175,105,.35);
  color:var(--gold-2);font-family:var(--serif);font-size:12px;
}
.help-step b{display:block;font-size:10px;letter-spacing:.1em;text-transform:uppercase;margin-bottom:3px}
.help-step p{margin:0;font-size:10px;line-height:1.55;color:var(--muted)}
.help-legend{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:18px}
.help-legend span{font-size:8px;letter-spacing:.1em;color:var(--muted);display:flex;align-items:center;gap:6px;text-transform:uppercase}
.help-legend i{width:7px;height:7px;border-radius:50%;display:inline-block}

/* ============================================================
   MOBİL / TABLET
   ============================================================ */
@media(max-width:1120px){
  .left-panel{width:276px}
  .right-panel{width:296px}
  .hud-side{max-width:190px}
  .hud-center{min-width:170px}
  .intro-grid{gap:3vw;padding-top:4vh}
}
@media(max-width:900px){
  .side-panel{top:84px;bottom:98px}
  .left-panel{left:8px;width:min(320px,86vw);transform:translateX(-112%);opacity:0;pointer-events:none}
  .right-panel{right:8px;left:8px;top:auto;bottom:98px;width:auto;height:min(48vh,420px);transform:translateY(112%);opacity:0;pointer-events:none}
