const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const errors = [];
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  await page.goto('http://localhost:8124/index.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(800);
  await page.screenshot({ path: '/tmp/shots3/intro.png' });
  await page.click('#btn-start');
  await page.waitForTimeout(1200);
  // dismiss any event modal
  for (let i = 0; i < 3; i++) {
    if (await page.locator('#event-modal:not(.hidden)').count()) {
      await page.click('#event-continue');
      await page.waitForTimeout(400);
    }
  }
  await page.screenshot({ path: '/tmp/shots3/game-desktop.png' });
  const info = await page.evaluate(() => {
    const s = window.BH.state;
    return {
      mode: s.mode, turn: s.turn, scenario: s.scenarioId, side: s.side,
      cam: window.BH.map.cam,
      owned: Object.entries(s.regions).filter(([,v]) => v.owner === s.side).map(([k]) => k),
    };
  });
  console.log(JSON.stringify(info, null, 2));
  console.log('ERRORS', JSON.stringify(errors, null, 2));
  await browser.close();
})();

