const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const errors = [];
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  await page.goto('http://localhost:8124/index.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(700);
  await page.click('#btn-start');
  await page.waitForTimeout(1000);
  for (let i = 0; i < 4; i++) {
    if (await page.locator('#event-continue').count()) {
      await page.click('#event-continue');
      await page.waitForTimeout(500);
    }
  }
  await page.evaluate(() => window.BH.ui.showAttackDialog('GER', 'POL'));
  await page.waitForTimeout(400);
  await page.screenshot({ path: '/tmp/shots3/attack-dialog.png' });
  const before = await page.evaluate(() => ({
    pol: { ...window.BH.state.regions.POL },
    ger: { ...window.BH.state.regions.GER },
    modal: window.BH.state.modalOpen,
  }));
  await page.click('#attack-confirm');
  await page.waitForTimeout(900);
  await page.screenshot({ path: '/tmp/shots3/after-attack.png' });
  const after = await page.evaluate(() => ({
    pol: { ...window.BH.state.regions.POL },
    ger: { ...window.BH.state.regions.GER },
    modal: window.BH.state.modalOpen,
    log: window.BH.state.log.slice(0, 3),
    stats: window.BH.state.stats,
    save: !!localStorage.getItem('buyuk-harp-save-v1'),
  }));
  console.log('BEFORE', JSON.stringify(before, null, 2));
  console.log('AFTER', JSON.stringify(after, null, 2));

  // End turn -> AI phase
  await page.click('#end-turn');
  await page.waitForTimeout(600);
  await page.screenshot({ path: '/tmp/shots3/ai-turn.png' });
  await page.waitForFunction(() => !window.BH.state.aiThinking, { timeout: 20000 }).catch(() => {});
  await page.waitForTimeout(700);
  for (let i = 0; i < 4; i++) {
    if (await page.locator('#event-continue').count()) {
      await page.click('#event-continue');
      await page.waitForTimeout(400);
    }
  }
  await page.screenshot({ path: '/tmp/shots3/turn2.png' });
  const turn2 = await page.evaluate(() => ({
    turn: window.BH.state.turn, date: window.BH.state.date,
    aiThinking: window.BH.state.aiThinking,
    modalOpen: window.BH.state.modalOpen,
    log: window.BH.state.log.slice(0, 6),
  }));
  console.log('TURN2', JSON.stringify(turn2, null, 2));
  console.log('ERRORS', JSON.stringify(errors, null, 2));
  await browser.close();
})();

