const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const errors = [];
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  await page.goto('http://localhost:8124/index.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(600);
  await page.click('#btn-start');
  await page.waitForTimeout(900);
  for (let i = 0; i < 4; i++) {
    if (await page.locator('#event-continue').count()) { await page.click('#event-continue'); await page.waitForTimeout(400); }
  }

  // Force a near-certain capture: weaken Poland and boost Germany.
  await page.evaluate(() => {
    const s = window.BH.state;
    s.regions.POL.troops = 1;
    s.regions.GER.troops = 20;
    window.BH.ui.selectRegion('GER');
    window.BH.ui.update();
  });
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/shots3/region-panel.png' });
  await page.evaluate(() => window.BH.ui.showAttackDialog('GER', 'POL'));
  await page.waitForTimeout(300);
  await page.click('#attack-confirm');
  await page.waitForTimeout(800);
  await page.screenshot({ path: '/tmp/shots3/capture.png' });
  const cap = await page.evaluate(() => ({
    pol: { ...window.BH.state.regions.POL },
    ger: { ...window.BH.state.regions.GER },
    morale: window.BH.state.factions,
    stats: window.BH.state.stats,
    banner: document.querySelector('#battle-banner') ? document.querySelector('#battle-banner').innerText : null,
    log: window.BH.state.log.filter(l => l.type === 'capture').slice(-2),
  }));
  console.log('CAPTURE', JSON.stringify(cap, null, 2));

  // Recruit / fortify via region panel buttons
  await page.evaluate(() => window.BH.ui.selectRegion('GER'));
  await page.waitForTimeout(300);
  const recruitBtn = page.locator('[data-action="recruit"]');
  const fortBtn = page.locator('[data-action="fortify"]');
  const beforeActions = await page.evaluate(() => ({ t: window.BH.state.regions.GER.troops, e: window.BH.state.regions.GER.entrench, gold: window.BH.state.factions.axis.treasury }));
  if (await recruitBtn.isEnabled()) await recruitBtn.click();
  await page.waitForTimeout(300);
  if (await fortBtn.isEnabled()) await fortBtn.click();
  await page.waitForTimeout(400);
  const afterActions = await page.evaluate(() => ({ t: window.BH.state.regions.GER.troops, e: window.BH.state.regions.GER.entrench, gold: window.BH.state.factions.axis.treasury }));
  console.log('ACTIONS', JSON.stringify({ beforeActions, afterActions }));

  // Save + reload
  await page.evaluate(() => window.BH.game.saveGame());
  await page.waitForTimeout(300);
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(700);
  const continueVisible = await page.locator('#btn-continue:not(.hidden)').count();
  await page.click('#btn-continue');
  await page.waitForTimeout(900);
  for (let i = 0; i < 4; i++) {
    if (await page.locator('#event-continue').count()) { await page.click('#event-continue'); await page.waitForTimeout(400); }
  }
  const reloaded = await page.evaluate(() => ({
    mode: window.BH.state.mode, turn: window.BH.state.turn,
    pol: { ...window.BH.state.regions.POL },
    ger: { ...window.BH.state.regions.GER },
    logCount: window.BH.state.log.length,
  }));
  console.log('RELOAD', JSON.stringify({ continueVisible, reloaded }, null, 2));

  // End screen
  await page.evaluate(() => window.BH.ui.showEnd('win', 'Tüm stratejik hedefler ele geçirildi.'));
  await page.waitForTimeout(600);
  await page.screenshot({ path: '/tmp/shots3/end.png' });
  console.log('ERRORS', JSON.stringify(errors, null, 2));
  await browser.close();
})();

