function updateLog() {
  if (!el.logList) return;
  if (!state.log.length) { el.logList.innerHTML = '<div class="log-entry"><p>Sefer günlüğü henüz boş.</p></div>'; return; }
  const items = state.log.slice().reverse();
  el.logList.innerHTML = items.map((e, i) => {
