const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const errors = [];
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  const page = await ctx.newPage();
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  await page.goto('http://localhost:8124/index.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(900);
  await page.screenshot({ path: '/tmp/shots3/mobile-intro.png' });
  await page.tap('#btn-start');
  await page.waitForTimeout(1000);
  // Capture the first historical event modal on mobile.
  if (await page.locator('#event-continue').count()) {
    await page.screenshot({ path: '/tmp/shots3/mobile-event.png' });
    await page.tap('#event-continue');
    await page.waitForTimeout(500);
  }
  for (let i = 0; i < 4; i++) {
    if (await page.locator('#event-continue').count()) { await page.tap('#event-continue'); await page.waitForTimeout(400); }
  }
  await page.screenshot({ path: '/tmp/shots3/mobile-game.png' });
  const cam = await page.evaluate(() => ({ cam: window.BH.map.cam, W: innerWidth, H: innerHeight }));
  console.log('MOBILE CAM', JSON.stringify(cam));

  // Open journal via menu.
  await page.tap('#btn-menu');
  await page.waitForTimeout(400);
  await page.screenshot({ path: '/tmp/shots3/mobile-menu.png' });
  await page.tap('[data-menu="journal"]');
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/shots3/mobile-journal.png' });
  await page.tap('#btn-close-left');
  await page.waitForTimeout(300);

  await page.evaluate(() => window.BH.ui.selectRegion('GER'));
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/shots3/mobile-region.png' });

  await page.evaluate(() => window.BH.ui.showAttackDialog('GER', 'POL'));
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/shots3/mobile-attack.png' });
  const dlg = await page.evaluate(() => ({
    modal: window.BH.state.modalOpen,
    rect: (() => { const r = document.querySelector('.modal-card').getBoundingClientRect(); return { x: r.x, y: r.y, w: r.width, h: r.height }; })(),
    scroll: document.querySelector('.modal-card').scrollHeight,
    viewport: { w: innerWidth, h: innerHeight },
  }));
  console.log('MOBILE DIALOG', JSON.stringify(dlg));
  await page.tap('#attack-cancel');
  await page.waitForTimeout(300);
  console.log('ERRORS', JSON.stringify(errors, null, 2));
  await browser.close();
})();

