const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  const page = await ctx.newPage();
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  await page.goto('http://localhost:8124/index.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(700);
  await page.tap('#btn-start');
  await page.waitForTimeout(900);
  for (let i = 0; i < 4; i++) {
    if (await page.locator('#event-continue').count()) { await page.tap('#event-continue'); await page.waitForTimeout(300); }
  }
  const before = await page.evaluate(() => ({ x: window.BH.cam.x, y: window.BH.cam.y, scale: window.BH.cam.scale }));
  const cdp = await ctx.newCDPSession(page);
  const pts = (d) => [
    { x: 160 - d, y: 300, id: 1, radiusX: 4, radiusY: 4, force: 1 },
    { x: 160 + d, y: 300, id: 2, radiusX: 4, radiusY: 4, force: 1 },
  ];
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: pts(30) });
  for (let i = 1; i <= 8; i++) {
    await cdp.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: pts(30 + i * 12) });
    await page.waitForTimeout(20);
  }
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  await page.waitForTimeout(400);
  const afterPinch = await page.evaluate(() => ({ x: window.BH.cam.x, y: window.BH.cam.y, scale: window.BH.cam.scale }));

  // Drag pan
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: 200, y: 250, id: 1, radiusX: 4, radiusY: 4, force: 1 }] });
  for (let i = 1; i <= 6; i++) {
    await cdp.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: 200 - i * 15, y: 250 + i * 8, id: 1, radiusX: 4, radiusY: 4, force: 1 }] });
    await page.waitForTimeout(20);
  }
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
  await page.waitForTimeout(400);
  const afterDrag = await page.evaluate(() => ({ x: window.BH.cam.x, y: window.BH.cam.y, scale: window.BH.cam.scale }));
  console.log(JSON.stringify({ before, afterPinch, afterDrag }, null, 2));
  await page.screenshot({ path: '/tmp/shots3/mobile-pinch.png' });
  console.log('ERRORS', JSON.stringify(errors, null, 2));
  await browser.close();
})();

