const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto('http://localhost:8124/index.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(600);
  await page.click('#btn-start');
  await page.waitForTimeout(800);
  for (let i = 0; i < 4; i++) {
    if (await page.locator('#event-continue').count()) { await page.click('#event-continue'); await page.waitForTimeout(300); }
  }
  const before = await page.evaluate(() => ({ x: window.BH.cam.x, y: window.BH.cam.y, scale: window.BH.cam.scale }));
  await page.mouse.move(700, 450);
  await page.mouse.down();
  await page.mouse.move(620, 420, { steps: 10 });
  await page.mouse.up();
  await page.waitForTimeout(400);
  const afterDrag = await page.evaluate(() => ({ x: window.BH.cam.x, y: window.BH.cam.y, scale: window.BH.cam.scale }));
  await page.mouse.move(700, 450);
  await page.mouse.wheel(0, -400);
  await page.waitForTimeout(400);
  const afterWheel = await page.evaluate(() => ({ x: window.BH.cam.x, y: window.BH.cam.y, scale: window.BH.cam.scale }));
  console.log(JSON.stringify({ before, afterDrag, afterWheel }, null, 2));
  await browser.close();
})();

