const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const logs = [];
  page.on('console', m => logs.push(m.text()));
  await page.goto('http://localhost:8124/index.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(600);
  await page.click('#btn-start');
  await page.waitForTimeout(800);
  for (let i = 0; i < 4; i++) {
    if (await page.locator('#event-continue').count()) { await page.click('#event-continue'); await page.waitForTimeout(300); }
  }
  await page.evaluate(() => {
    window.__ev = [];
    for (const t of ['pointerdown', 'pointermove', 'pointerup']) {
      document.addEventListener(t, e => window.__ev.push({ t, target: e.target.id || e.target.className, x: e.clientX, y: e.clientY, id: e.pointerId, type: e.pointerType }), true);
    }
    const c = document.querySelector('#map');
    c.addEventListener('pointerdown', e => console.log('CANVAS DOWN', e.clientX, e.clientY));
    c.addEventListener('pointermove', e => console.log('CANVAS MOVE', e.clientX, e.clientY));
  });
  const before = await page.evaluate(() => ({ x: window.BH.cam.x, y: window.BH.cam.y, scale: window.BH.cam.scale }));
  await page.mouse.move(700, 450);
  await page.mouse.down();
  await page.mouse.move(620, 420, { steps: 3 });
  await page.mouse.up();
  await page.waitForTimeout(300);
  const after = await page.evaluate(() => ({ cam: { x: window.BH.cam.x, y: window.BH.cam.y, scale: window.BH.cam.scale }, ev: window.__ev.slice(0, 10) }));
  console.log(JSON.stringify({ before, after }, null, 2));
  console.log(logs.join('\n'));
  await browser.close();
})();

